:root {
  --white: #12141d;
  --number-bg: #dbecfe;
  --header: #333;
  --charcoal: #141414;
  --new: #12141d;
  --333333: var(--header);
  --backg: #12141d;
  --steel-blue: #2787a5;
  --0b0b0b: var(--number-bg);
  --777d87: var(--white);
}

.w-layout-grid {
  grid-row-gap: 16px;
  grid-column-gap: 16px;
  grid-template-rows: auto auto;
  grid-template-columns: 1fr 1fr;
  grid-auto-columns: 1fr;
  display: grid;
}

.w-layout-blockcontainer {
  max-width: 940px;
  margin-left: auto;
  margin-right: auto;
  display: block;
}

@media screen and (max-width: 991px) {
  .w-layout-blockcontainer {
    max-width: 728px;
  }
}

@media screen and (max-width: 767px) {
  .w-layout-blockcontainer {
    max-width: none;
  }
}

body {
  background-color: var(--white);
  color: #fff;
  border-radius: 16px;
  font-family: graphik, sans-serif;
  font-size: 1vw;
  font-weight: 200;
  line-height: 1.5;
}

h1 {
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-top: 0;
  margin-bottom: 0;
  font-family: graphik, sans-serif;
  font-size: 19vh;
  font-weight: 300;
  line-height: 1.2;
}

h2 {
  margin-top: 0;
  margin-bottom: 0;
  font-family: Roboto, sans-serif;
  font-size: 6em;
  font-weight: 400;
  line-height: 1.3;
}

h3 {
  margin-top: 0;
  margin-bottom: 0;
  font-size: 3em;
  font-weight: 500;
  line-height: 1.4;
}

h4 {
  margin-top: 0;
  margin-bottom: 0;
  font-family: Roboto, sans-serif;
  font-size: 2.5em;
  font-weight: 400;
  line-height: 1.5;
}

h5 {
  margin-top: 0;
  margin-bottom: 0;
  font-family: Libre Caslon Display, sans-serif;
  font-size: 2em;
  font-weight: 400;
  line-height: 1.6;
}

h6 {
  margin-top: 0;
  margin-bottom: 0;
  font-family: Libre Caslon Display, sans-serif;
  font-size: 1.5em;
  font-weight: 400;
  line-height: 1.6;
}

p {
  margin-bottom: 0;
  font-size: 1.25em;
  line-height: 1.6;
}

a {
  font-size: 1em;
  text-decoration: underline;
}

strong {
  font-weight: 500;
}

.container {
  flex-direction: column;
  width: 100%;
  max-width: 1700px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 3rem;
  padding-right: 3rem;
  display: flex;
  position: static;
}

.container.hero-container {
  flex: 1;
  justify-content: center;
  align-items: center;
  display: flex;
}

.container.small {
  padding-left: 8rem;
  padding-right: 8rem;
}

.container.footer-content {
  z-index: 2;
  padding-left: 8em;
  padding-right: 8em;
}

.container.works {
  margin-left: 0;
  position: static;
}

.section {
  z-index: 1;
  padding-top: 10em;
  padding-bottom: 10em;
  position: relative;
}

.section.hero {
  flex-direction: column;
  min-height: 100vh;
  padding-top: 0;
  padding-bottom: 0;
  display: block;
  overflow: visible;
}

.section.call-to-action_mid {
  padding-top: 8em;
  padding-bottom: 8em;
  overflow: hidden;
}

.section.about {
  color: var(--number-bg);
  background-color: #fff;
  position: relative;
}

.section.contact {
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 100vh;
  max-height: 1000px;
  display: flex;
  overflow: hidden;
}

.section.light {
  color: var(--number-bg);
  background-color: #fff;
  display: none;
  overflow: hidden;
}

.section.projects {
  grid-column-gap: 0rem;
  grid-row-gap: 0rem;
  flex-flow: column;
  padding-top: 0;
  display: flex;
}

.section.project-hero {
  align-items: center;
  height: auto;
  min-height: 100vh;
  padding-top: 15em;
  display: flex;
}

.no-t-padding {
  padding-top: 0;
}

.no-b-padding {
  padding-bottom: 0;
}

.no-tb-padding {
  padding-top: 0;
  padding-bottom: 0;
}

.no-t-margin {
  margin-top: 0;
}

.no-b-margin {
  margin-bottom: 0;
}

.no-tb-margin {
  margin-top: 0;
  margin-bottom: 0;
}

.h2 {
  z-index: 99;
  background-color: #70707000;
  width: 100%;
  max-width: 100%;
  height: auto;
  margin-top: 0;
  margin-bottom: 0;
  display: none;
  position: fixed;
  inset: 0% 0% auto;
}

.h2.difference {
  mix-blend-mode: difference;
  padding-top: 1em;
}

.h2.no-diff {
  padding-top: 1em;
}

.h2.destop, .h2.other {
  display: block;
}

.navbar_logo {
  width: 100%;
  height: 100%;
}

.nav {
  grid-column-gap: 2em;
  grid-row-gap: 2em;
  grid-template-rows: auto;
  grid-template-columns: auto;
  grid-auto-columns: auto;
  grid-auto-flow: column;
  place-items: center stretch;
  height: 100%;
  padding-left: 2em;
  padding-right: 2em;
  font-family: Avertademo, sans-serif;
  display: grid;
}

.nav_link {
  color: #f7ebd9;
  text-transform: uppercase;
  padding: 16px 20px;
  font-family: graphik, sans-serif;
  font-size: 1em;
  font-weight: 400;
  text-decoration: none;
}

.nav_link:hover {
  background-color: #141414;
}

.nav_link.w--current {
  color: #f7ebd9;
  text-transform: uppercase;
  font-family: graphik, sans-serif;
}

.nav_link.black {
  color: #000;
  text-transform: none;
  font-family: Neuemontreal, Arial, sans-serif;
  font-size: 14px;
  display: block;
}

.nav_link.black:hover {
  background-color: #1414147d;
}

.nav_link._2 {
  text-transform: none;
  min-width: auto;
  font-family: Neuemontreal, Arial, sans-serif;
  font-size: 14px;
  position: static;
}

.nav_link._2:hover {
  background-color: #14141499;
}

.nav_link._1 {
  text-transform: none;
  font-family: Neuemontreal, Arial, sans-serif;
  font-size: 14px;
  font-weight: 400;
}

.nav_link._1:hover, .nav_link._1:active {
  background-color: #14141499;
}

.nav_link._1.w--current {
  background-color: #14141400;
  font-size: 14px;
}

.nav_link._1.w--current:hover, .nav_link._1.w--current:active {
  background-color: #14141499;
}

.navbar_inner {
  justify-content: space-between;
  align-items: center;
  width: 100%;
  max-width: 100%;
  padding-top: 0;
  padding-bottom: 0;
  display: flex;
}

.hero_inner {
  z-index: 3;
  perspective: 200px;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  width: 100%;
  display: flex;
  position: relative;
  transform: translate(0);
}

.hero_img-wrap {
  z-index: 1;
  perspective: 1000px;
  width: 70%;
  max-width: 55em;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  transform: perspective(2000px);
}

.hero_image {
  filter: brightness(65%);
  object-fit: cover;
  width: 70vw;
  height: 100%;
  min-height: 65vh;
  max-height: 85vh;
}

.hero_heading {
  text-align: center;
  letter-spacing: .01em;
  text-transform: uppercase;
  justify-content: center;
  width: 100%;
  font-size: 20vh;
  line-height: 1;
  display: flex;
}

.hero_heading.heading-1 {
  text-align: center;
  text-shadow: 0 0 4em #00000040;
  font-weight: 900;
}

.hero_heading.heading-2 {
  text-align: center;
  font-weight: 300;
}

.hero_heading.heading-3 {
  text-align: center;
  font-family: DM Serif Display, sans-serif;
  font-weight: 400;
}

.hero_heading.heading-4 {
  text-align: center;
  font-family: Roboto, sans-serif;
  font-weight: 300;
}

.hero_heading-wrap {
  z-index: 5;
  mix-blend-mode: overlay;
  width: 100%;
  transform-style: preserve-3d;
  flex-direction: column;
  display: flex;
  position: absolute;
  inset: 0%;
  transform: perspective(200px);
}

.hero_heading-wrap.control {
  display: none;
  position: absolute;
  inset: 0%;
}

.section_body {
  letter-spacing: 0;
  text-transform: none;
  font-weight: 400;
}

.section_body.large {
  color: #f7ebd9;
  align-self: center;
  max-width: none;
  font-family: Polysans Neutral, Arial, sans-serif;
  font-size: 44px;
  font-weight: 300;
